import json
from copy import deepcopy

def solve_puzzle():
    # Input puzzle variables
    houses = [1, 2]  # Houses numbered 1 to 2
    categories = {
        "Name": ["Eric", "Arnold"],
        "hobby": ["gardening", "photography"],
        "favorite book genres": ["science fiction", "mystery"],
        "favorite music genres": ["rock", "pop"],
        "birthday month": ["april", "sept"],
    }
    category_order = ["Name", "hobby", "favorite book genres", "favorite music genres", "birthday month"]

    # Initialize assignments: one dict per house
    assignments = []
    for h in houses:
        entry = {"House": h}
        for cat in categories:
            entry[cat] = None
        assignments.append(entry)

    # Constraint checker according to the clues
    def check_constraints(state):
        # Uniqueness constraints across houses for each category
        for cat, vals in categories.items():
            seen = set()
            for a in state:
                v = a.get(cat)
                if v is None:
                    continue
                if v in seen:
                    return False
                seen.add(v)

        # Clues:
        # 1. The person who loves mystery books is the person who loves rock music.
        # 3. The person who loves mystery books is the person who enjoys gardening.
        # 4. The person whose birthday is in April is Arnold.
        # 2. Arnold is not in the first house.
        # 5. The person who loves mystery books is in the first house.

        for idx, a in enumerate(state):
            book = a.get("favorite book genres")
            music = a.get("favorite music genres")
            hobby = a.get("hobby")
            name = a.get("Name")
            month = a.get("birthday month")

            # 1. mystery <-> rock
            if book == "mystery" and music is not None and music != "rock":
                return False
            if music == "rock" and book is not None and book != "mystery":
                return False

            # 3. mystery <-> gardening
            if book == "mystery" and hobby is not None and hobby != "gardening":
                return False
            if hobby == "gardening" and book is not None and book != "mystery":
                return False

            # 4. april <-> Arnold
            if month == "april" and name is not None and name != "Arnold":
                return False
            if name == "Arnold" and month is not None and month != "april":
                return False

        # 2. Arnold is not in the first house.
        if state[0].get("Name") == "Arnold":
            return False

        # 5. mystery is in the first house only
        # If house 1 has a book assigned and it is not mystery -> invalid
        if state[0].get("favorite book genres") is not None and state[0].get("favorite book genres") != "mystery":
            return False
        # If any other house has "mystery" assigned -> invalid
        for i in range(1, len(state)):
            if state[i].get("favorite book genres") == "mystery":
                return False

        return True

    # Backtracking solver
    def is_complete(state):
        for a in state:
            for cat in categories:
                if a.get(cat) is None:
                    return False
        return True

    def select_unassigned_variable(state):
        # Choose the next unassigned variable (house, category) in fixed order
        for h_index, a in enumerate(state):
            for cat in category_order:
                if a[cat] is None:
                    return (h_index, cat)
        return None

    def get_domain(state, h_index, cat):
        # Domain is the list of values not yet used in this category
        used = set()
        for i, a in enumerate(state):
            if i == h_index:
                continue
            v = a.get(cat)
            if v is not None:
                used.add(v)
        domain = [v for v in categories[cat] if v not in used]
        return domain

    def backtrack(state):
        if is_complete(state):
            return state

        var = select_unassigned_variable(state)
        if var is None:
            return None
        h_index, cat = var
        domain = get_domain(state, h_index, cat)

        for val in domain:
            new_state = deepcopy(state)
            new_state[h_index][cat] = val
            if check_constraints(new_state):
                result = backtrack(new_state)
                if result is not None:
                    return result
        return None

    solution = backtrack(assignments)
    if solution is None:
        raise ValueError("No solution found")

    # Build output JSON
    header = ["House"] + category_order
    rows = []
    # Ensure houses are in order 1..n
    solution_sorted = sorted(solution, key=lambda x: x["House"])
    for a in solution_sorted:
        row = [str(a["House"])]
        for cat in category_order:
            row.append(a[cat])
        rows.append(row)

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
